import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{Bn as n,Mr as r,en as i,t as a,wr as o}from"./icons-DTR6_mEc.js";import{n as s,t as c}from"./ArticleLayout-BOfzG3xJ.js";var l,u,d=e((()=>{a(),l=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurer la voiture d'un proche décédé : ce que dit la loi, et comment rouler couvert`,description:`Au décès, le contrat auto ne disparaît pas mais l'héritier n'est pas toujours couvert. Assurance temporaire pour déplacer ou vendre le véhicule, attestation immédiate.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-temporaire-vehicule-proche-decede`,datePublished:`2026-06-23`,dateModified:`2026-06-23`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Assurer la voiture d'un proche décédé`,item:`https://assutempo.fr/articles/assurance-temporaire-vehicule-proche-decede`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Le contrat d'assurance du défunt couvre-t-il les héritiers ?`,acceptedAnswer:{"@type":`Answer`,text:`Au décès, le contrat se transmet de plein droit aux héritiers (article L121-10 du Code des assurances), qui reprennent les obligations, dont le paiement des primes. Mais l'héritier qui conduit n'est pas toujours un conducteur déclaré : la couverture peut être incertaine. Vérifiez les conditions auprès de l'assureur.`}},{"@type":`Question`,name:`Peut-on conduire la voiture d'une personne décédée ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, à condition que le véhicule soit assuré au minimum en responsabilité civile. Si le contrat du défunt est inconnu, suspendu ou ne vous autorise pas à conduire, une assurance temporaire à votre nom vous couvre immédiatement.`}},{"@type":`Question`,name:`Faut-il une assurance pour vendre ou faire convoyer la voiture ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui. Tant que le véhicule circule, la responsabilité civile est obligatoire. Une assurance temporaire à votre nom permet de déplacer ou de présenter la voiture à un acheteur sans dépendre du contrat du défunt.`}},{"@type":`Question`,name:`La carte grise doit-elle d'abord être à mon nom ?`,acceptedAnswer:{"@type":`Answer`,text:`Non. Comme pour un véhicule fraîchement acheté, vous pouvez assurer la voiture même si la carte grise est encore au nom du défunt, le temps des démarches de succession.`}},{"@type":`Question`,name:`Que devient le contrat quand la voiture est vendue ?`,acceptedAnswer:{"@type":`Answer`,text:`À la vente, l'article L121-11 du Code des assurances s'applique : le contrat est suspendu le lendemain de la cession à minuit, résiliable avec un préavis de 10 jours, et résilié de plein droit au bout de 6 mois. L'acheteur doit s'assurer dès la remise du véhicule.`}},{"@type":`Question`,name:`Plusieurs héritiers : qui paie l'assurance ?`,acceptedAnswer:{"@type":`Answer`,text:`Si le contrat transmis se poursuit, les héritiers sont solidairement tenus du paiement des primes. C'est une raison de plus pour clarifier vite la situation et, si besoin, basculer sur une assurance temporaire au nom de celui qui utilise le véhicule.`}},{"@type":`Question`,name:`L'assurance temporaire convient-elle dans une succession ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, c'est un pont idéal : elle couvre celui qui doit déplacer ou vendre le véhicule, de 1 à 90 jours, sans engager un contrat à l'année pour une voiture destinée à être cédée.`}}]}],u={slug:`assurance-temporaire-vehicule-proche-decede`,seo:{title:`Voiture d'un proche décédé : comment l'assurer et la conduire`,description:`Au décès, le contrat auto ne disparaît pas mais l'héritier n'est pas toujours couvert. Assurance temporaire pour déplacer ou vendre le véhicule, attestation immédiate.`,canonical:`https://assutempo.fr/articles/assurance-temporaire-vehicule-proche-decede`,jsonLd:l},category:`Succession`,readTime:`5 min`,updatedDate:`23 juin 2026`,author:`Evidence Assurances`,headline:`Assurer la voiture d'un proche décédé : ce que dit la loi, et comment rouler couvert`,immediateAnswer:`Au décès du propriétaire, le contrat d'assurance auto ne s'éteint pas automatiquement : il se transmet de plein droit aux héritiers (article L121-10 du Code des assurances), qui reprennent les obligations, dont le paiement des primes. Mais en pratique, l'héritier qui prend le volant n'est pas toujours un conducteur déclaré au contrat, et parfois le contrat est inconnu, suspendu ou déjà résilié. Pour déplacer ou vendre le véhicule sereinement, une assurance temporaire à votre nom vous couvre immédiatement, sans dépendre du contrat du défunt ni engager un contrat annuel pour une voiture que vous allez céder.`,sections:[{type:`text`,heading:`Le contrat du défunt ne disparaît pas du jour au lendemain`,paragraphs:[`C'est une idée reçue tenace : non, l'assurance ne s'arrête pas mécaniquement au décès. La loi prévoit l'inverse. En cas de décès de l'assuré, le contrat se transmet de plein droit aux héritiers, qui doivent exécuter les obligations du défunt, à commencer par le paiement des primes (article L121-10 du Code des assurances). L'assureur, comme les héritiers, peut ensuite décider de le résilier.`,`Sur le papier, la voiture reste donc couverte un temps. En pratique, plusieurs grains de sable viennent compliquer les choses, et c'est là que la question de l'assurance se pose vraiment.`]},{type:`alert`,heading:`Là où ça coince en pratique`,items:[`L'héritier qui conduit n'est pas un conducteur déclaré au contrat : la couverture peut être incertaine`,`Le contrat est introuvable, la prime impayée depuis le décès, ou le contrat déjà résilié`,`Plusieurs héritiers se partagent le véhicule et sont solidaires des primes`,`La voiture doit être déplacée ou vendue vite, sans attendre la fin de la succession`],note:`Dans tous ces cas, s'appuyer sur le contrat du défunt est un pari. Une couverture claire à votre nom lève le doute.`},{type:`text`,heading:`Premier réflexe : vérifier s'il existe un contrat valide`,paragraphs:[`Avant toute chose, cherchez les documents du véhicule : carte grise, dernier avis d'échéance, relevé d'information. Contactez l'assureur du défunt pour savoir si le contrat est toujours actif, si les primes sont à jour, et surtout si vous êtes autorisé à conduire en tant qu'héritier.`,`Si la réponse est claire et que vous êtes couvert, vous n'avez peut-être pas besoin d'autre chose. Mais dès qu'un doute subsiste, sur l'existence du contrat, son paiement ou la liste des conducteurs, mieux vaut une solution nette que de rouler en espérant être couvert.`]},{type:`callout`,title:`Le cas le plus fréquent`,icon:`navigation`,text:`Souvent, la voiture doit simplement être déplacée du domicile, amenée chez un proche, ou présentée à un acheteur, avant même que la succession soit réglée. Personne ne souhaite payer une année d'assurance pour cela. Une assurance temporaire au nom de celui qui conduit règle la question en quelques minutes.`},{type:`stepflow`,ariaLabel:`Déplacer ou vendre le véhicule en quatre étapes`,steps:[{icon:n,label:`Rassemblez les papiers du véhicule`},{icon:o,label:`Vérifiez la couverture existante`},{icon:r,label:`En cas de doute, souscrivez à votre nom`},{icon:i,label:`Attestation immédiate, vous roulez`}]},{type:`text`,heading:`La carte grise au nom du défunt n'est pas un obstacle`,paragraphs:[`Pendant les démarches de succession, le certificat d'immatriculation reste généralement au nom du défunt : c'est normal, la mutation prend du temps. Cela n'empêche pas d'assurer le véhicule. Comme pour une voiture achetée à un particulier et pas encore réimmatriculée, l'assurance temporaire couvre le conducteur et le véhicule désignés, même si la carte grise n'est pas encore à jour.`],relatedLink:{text:`Rouler en attendant sa carte grise définitive`,href:`/articles/assurance-temporaire-rouler-en-attendant-carte-grise`}},{type:`text`,heading:`Et quand la voiture est vendue ?`,paragraphs:[`Si les héritiers décident de céder le véhicule, c'est un autre article qui prend le relais. À la vente, le contrat d'assurance en cours est suspendu le lendemain de la cession à minuit, peut être résilié avec un préavis de 10 jours, et l'est de plein droit au bout de 6 mois (article L121-11 du Code des assurances). De son côté, l'acheteur doit être assuré dès la remise des clés : la loi ne prévoit aucun délai de grâce.`],relatedLink:{text:`Assurer un véhicule acheté chez un particulier`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`checklist`,heading:`Les documents utiles pour conduire le véhicule`,items:[`Un permis de conduire valide, adapté à la catégorie du véhicule`,`Une attestation d'assurance en cours de validité (responsabilité civile au minimum)`,`La carte grise, même encore au nom du défunt`,`Un justificatif de votre qualité d'héritier, utile pour les démarches`],note:`Pour conduire, le permis et l'attestation d'assurance sont les deux pièces indispensables à présenter en cas de contrôle.`},{type:`text`,heading:`En résumé`,paragraphs:[`Perdre un proche s'accompagne déjà d'assez de démarches. Pour le véhicule, retenez l'essentiel : le contrat ne s'éteint pas tout seul, mais il ne vous couvre pas toujours. Vérifiez d'abord ce qui existe ; au moindre doute, une assurance temporaire à votre nom vous permet de déplacer ou de vendre la voiture en règle, attestation immédiate, sans engager un contrat à l'année pour un véhicule que vous allez céder.`],relatedLink:{text:`Voiture immobilisée pour défaut d'assurance : la récupérer`,href:`/articles/voiture-immobilisee-defaut-assurance`}}],faqItems:[{q:`Le contrat d'assurance du défunt couvre-t-il les héritiers ?`,a:`Il se transmet de plein droit aux héritiers (L121-10), mais l'héritier qui conduit n'est pas toujours un conducteur déclaré : la couverture peut être incertaine. Vérifiez auprès de l'assureur.`},{q:`Peut-on conduire la voiture d'une personne décédée ?`,a:`Oui si le véhicule est assuré au minimum en responsabilité civile. Si le contrat est inconnu ou ne vous autorise pas à conduire, une temporaire à votre nom vous couvre tout de suite.`},{q:`Faut-il une assurance pour vendre ou convoyer la voiture ?`,a:`Oui, dès que le véhicule circule. Une temporaire à votre nom permet de le déplacer ou de le présenter à un acheteur sans dépendre du contrat du défunt.`},{q:`La carte grise doit-elle d'abord être à mon nom ?`,a:`Non. Comme pour un véhicule fraîchement acheté, on peut l'assurer même si la carte grise reste au nom du défunt le temps de la succession.`},{q:`Que devient le contrat à la vente du véhicule ?`,a:`Suspension le lendemain de la cession à minuit, résiliation possible sous 10 jours de préavis, résiliation de plein droit au bout de 6 mois (L121-11). L'acheteur doit s'assurer dès la remise.`},{q:`Plusieurs héritiers, qui paie les primes ?`,a:`Si le contrat transmis se poursuit, les héritiers en sont solidairement tenus. D'où l'intérêt de clarifier vite et, au besoin, de passer sur une temporaire au nom de celui qui roule.`},{q:`L'assurance temporaire convient-elle dans une succession ?`,a:`Oui, c'est un pont : elle couvre celui qui déplace ou vend le véhicule, de 1 à 90 jours, sans contrat à l'année pour une voiture destinée à être cédée.`}]}}));function f(){return(0,p.jsx)(c,{data:u})}var p;e((()=>{s(),d(),p=t()}))();export{f as default};